package say

import "strings"

const maxNumber = 999_999_999_999

var ones = []string{
	"zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
	"ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
	"seventeen", "eighteen", "nineteen",
}

var tens = []string{
	"", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
}

var scales = []string{"", "thousand", "million", "billion"}

// Say spells out the given integer as English words.
// It returns an error (ok == false) if the input is outside the range
// 0 to 999,999,999,999.
func Say(n int64) (string, bool) {
	if n < 0 || n > maxNumber {
		return "", false
	}

	if n == 0 {
		return "zero", true
	}

	var parts []string
	scale := 0
	for n > 0 {
		if chunk := n % 1000; chunk > 0 {
			part := under1000(chunk)
			if scale > 0 {
				part += " " + scales[scale]
			}
			parts = append(parts, part)
		}
		n /= 1000
		scale++
	}

	// Chunks were collected least-significant first; reverse them.
	for i, j := 0, len(parts)-1; i < j; i, j = i+1, j-1 {
		parts[i], parts[j] = parts[j], parts[i]
	}

	return strings.Join(parts, " "), true
}

// under1000 spells out a number in the range 1 to 999.
func under1000(n int64) string {
	var parts []string
	if n >= 100 {
		parts = append(parts, ones[n/100]+" hundred")
		n %= 100
	}
	if n >= 20 {
		word := tens[n/10]
		if n%10 > 0 {
			word += "-" + ones[n%10]
		}
		parts = append(parts, word)
	} else if n > 0 {
		parts = append(parts, ones[n])
	}
	return strings.Join(parts, " ")
}
